import {createHash} from 'node:crypto';
import {readFileSync, writeFileSync} from 'node:fs';
import {HEADERS} from '../docs/import/core.mjs';
import {SAMPLE_INVOICES, SAMPLE_PAYMENTS} from '../docs/import/sample.mjs';
const base = new URL('../docs/import/', import.meta.url);
const digest = createHash('sha256').update(readFileSync(new URL('core.mjs', base))).digest('hex');
const generated = {
  'identity.mjs': `// Generated by node scripts/build-import.mjs; CI verifies source identity.\nexport const ENGINE_SHA256 = '${digest}';\n`,
  'invoices-template.csv': HEADERS.invoices.join(',') + '\n',
  'payments-template.csv': HEADERS.payments.join(',') + '\n',
  'sample-invoices.csv': SAMPLE_INVOICES,
  'sample-payments.csv': SAMPLE_PAYMENTS,
};
for (const [name, contents] of Object.entries(generated)) {
  const path = new URL(name, base);
  if (process.argv.includes('--check')) {
    if (readFileSync(path, 'utf8') !== contents) throw new Error(`${name} is stale; run node scripts/build-import.mjs`);
  } else writeFileSync(path, contents);
}
console.log(`Local import static assets ${process.argv.includes('--check') ? 'verified' : 'generated'}.`);
